#!/usr/bin/env bash
# PreToolUse hook (Edit|Write): guard files that should not be hand-edited.
#   - cli/bootstrap_iac/templates/  generated bundle -> deny
#   - examples/generated/           generated by build_examples.py -> ask
#   - *.tmpl                        read-only per CLAUDE.md -> ask
# Set IAC_ALLOW_TMPL_EDIT=1 to skip the .tmpl prompt when maintaining templates.
set -euo pipefail

file=$(jq -r '.tool_input.file_path // empty')
[[ -n "$file" ]] || exit 0

decide() {
  jq -n --arg d "$1" --arg r "$2" '{hookSpecificOutput: {hookEventName: "PreToolUse", permissionDecision: $d, permissionDecisionReason: $r}}'
  exit 0
}

case "$file" in
  */cli/bootstrap_iac/templates/*)
    decide deny "Generated bundle (gitignored). Edit references/ and run: python scripts/build_templates.py" ;;
  */examples/generated/*)
    decide ask "Generated by scripts/build_examples.py from the committed .bootstrap-iac.yaml; hand edits are overwritten. Edit the template or config and regenerate instead." ;;
  *.tmpl)
    [[ "${IAC_ALLOW_TMPL_EDIT:-}" == "1" ]] && exit 0
    decide ask "CLAUDE.md marks .tmpl files read-only. Confirm this is an intentional template change (set IAC_ALLOW_TMPL_EDIT=1 to skip this prompt)." ;;
esac
